29| export class ClubBookingService {
30|   /** hourlyRateCents is the club rate for the whole rink; a half rink is charged at half of it. */
31|   constructor(
32|     private readonly clubBookings: ClubBookingRepository,
33|     private readonly hourlyRateCents: number = DEFAULT_CLUB_RATE_CENTS,
34|     private readonly now: () => number = Date.now,
35|   ) {}
36| 
37|   create(input: NewClubBooking): ClubBooking {
38|     if (typeof input.date !== "string" || !DATE.test(input.date) || Number.isNaN(Date.parse(input.date)))
39|       throw new DomainError(400, "date must be YYYY-MM-DD");
40|     if (typeof input.start !== "string" || typeof input.end !== "string" ||
41|         !HOUR.test(input.start) || !HOUR.test(input.end))
42|       throw new DomainError(400, "start and end must be whole hours (HH:00)");
43|     if (input.end <= input.start) throw new DomainError(400, "end must be after start");
44|     if (!AREAS.includes(input.area)) throw new DomainError(400, "area must be whole, half-a or half-b");
45| 
46|     const clash = this.clubBookings
47|       .findByDate(input.date)
48|       .some(
49|         (c) =>
50|           c.start < input.end && input.start < c.end &&
51|           (c.area === "whole" || input.area === "whole" || c.area === input.area),
52|       );
53|     if (clash) throw new DomainError(409, "overlaps an existing club booking");
54| 
55|     return this.clubBookings.create({
56|       date: input.date, start: input.start, end: input.end, area: input.area, createdAt: this.now(),
57|     });
58|   }
59| 
60|   list(): ClubBooking[] {
61|     return this.clubBookings.findAll();
62|   }
63| 
64|   invoice(month: string): ClubInvoice {
65|     if (typeof month !== "string" || !MONTH.test(month))
66|       throw new DomainError(400, "month must be YYYY-MM");
67|     const bookings = this.clubBookings
68|       .findByMonth(month)
69|       .sort((a, b) => (a.date + a.start).localeCompare(b.date + b.start))
70|       .map((b) => {
71|         const hours = hourOf(b.end) - hourOf(b.start);
72|         const factor = b.area === "whole" ? 1 : 0.5;
73|         return { ...b, hours, amountCents: Math.round(hours * factor * this.hourlyRateCents) };
74|       });
75|     return {
76|       month,
77|       hourlyRateCents: this.hourlyRateCents,
78|       bookings,
79|       totalHours: bookings.reduce((n, b) => n + b.hours, 0),
80|       totalCents: bookings.reduce((n, b) => n + b.amountCents, 0),
81|     };
82|   }
83| }
